        "code": "GHS04"
      }
    ],
    "h_statements": [
      {
        "code": "EUH290",
        "text": "고압가스 포함",
        "line": "p2:L19"
      },
      {
        "code": "EUH290",
        "text": "가열하면 폭발할 수 있음",
        "line": "p2:L19"
      }
    ],
    "p_statements": [
      {
        "code": "P403",
        "type": "저장",
        "text": "용기는 조심해서 다루고, 충격을 주거나 전도되지 않게 하시오",
        "line": "p2:L21"
      },
      {
        "code": "P403",
        "type": "저장",
        "text": "용기가 장시간 직사광선이나 화기에 노출되면, 용기내부 가스압력이 급상승하여 용기 밸브(용기)파열의 위험성이 있으니 40℃이하의 그늘진 곳에 보관하여 주십시오.",
        "line": "p2:L22"
      },
      {
        "code": "P304+P310",
        "type": "대응",
        "text": "가스를 다량 흡입시 질식할 위험이 있으므로, 신속히 신선한 공기가 있는 곳으로 이동하여 필요한 만큼의 산소를 흡입케 하고, 호흡하지 않을 경우 인공호흡을 하고, 즉시 의사의 치료를 받으시오.",
        "line": "p2:L25"
      },
      {
        "code": "P403",
        "type": "저장",
        "text": "직사광선을 피하고 환기가 잘 되는 곳에 보관하시오.",
        "line": "p2:L28"
      },
      {
        "code": "P403",
        "type": "저장",
        "text": "사용후에는 용기 밸브를 완전히 잠그고, 용기 캡을 안전하게 씌우시오.",
        "line": "p2:L29"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "관련 법규에 명시된 경우 규정에 따라 내용물, 용기를 폐기하시오.",
        "line": "p2:L30"
      }
    ],
    "nfpa": {
      "health": 0,
      "fire": 0,
      "reactivity": 0,
      "special": "고압가스"
    },
    "lines": {
      "pictograms": "p2:L17",
      "nfpa": "p2:L32"
    }
  },
  "narratives": [
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "가.그림문자",
      "start": "p2:L17",
      "end": "p2:L17"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "나.신호어",
      "start": "p2:L18",
      "end": "p2:L18"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "다.유해위험문구",
      "start": "p2:L19",
      "end": "p2:L19"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "라.예방조치문구",
      "start": "p2:L20",
      "end": "p2:L30"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "마. 유해 위험성 분류기준에 포함되지 않는 기타 유해 위험성",
      "start": "p2:L31",
      "end": "p2:L32"
    }
  ]
  ,
  "extras": [
